const DIRS = [[-1, 0], [1, 0], [0, -1], [0, 1]];

function solve(board) {
  const rows = board.length, cols = board[0].length;
  const seen = board.map((row) => row.map(() => false));
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (board[r][c] !== "O" || seen[r][c]) continue;
      // Collect this whole region, noting whether any cell is on the border.
      const region = [[r, c]];
      seen[r][c] = true;
      let touchesBorder = false;
      for (let i = 0; i < region.length; i++) {
        const [cr, cc] = region[i];
        if (cr === 0 || cr === rows - 1 || cc === 0 || cc === cols - 1) touchesBorder = true;
        for (const [dr, dc] of DIRS) {
          const nr = cr + dr, nc = cc + dc;
          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] === "O" && !seen[nr][nc]) {
            seen[nr][nc] = true;
            region.push([nr, nc]);
          }
        }
      }
      if (!touchesBorder) for (const [cr, cc] of region) board[cr][cc] = "X";   // surrounded: capture it
    }
  }
}

